  CUSTOMER_OPT_OUT: 'ลูกค้ายกเลิกความยินยอม', DRY_RUN_ENQUEUED: 'ทดลองส่ง (ไม่ยิง LINE)',
  FLEX_REVISION_CREATED: 'บันทึกเวอร์ชันการ์ด', MANUAL_PUSH_PREVIEWED: 'ดูตัวอย่างข้อความตรง',
